def has_cycle(graph):
    """
    Detects whether an undirected graph contains a cycle using DFS.

    Args:
        graph (List[List[int]]): Adjacency list representation of the graph.
                                 graph[i] is a list of vertices adjacent to vertex i.

    Returns:
        bool: True if a cycle exists, False otherwise.
    """
    n = len(graph)
    visited = [False] * n

    def dfs(node, parent):
        """Recursive DFS helper that returns True if a cycle is found in the component."""
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, node):
                    return True
            elif neighbor != parent:
                # visited neighbor that is not the parent → cycle
                return True
        return False

    # Check all connected components
    for v in range(n):
        if not visited[v]:
            if dfs(v, -1):
                return True
    return False

