Below is a **stand‑alone C++ function** that performs a Breadth‑First Search (BFS) on a graph represented by an adjacency list.  
The function returns the order in which the vertices are visited.  
It works for both directed and undirected graphs – you just need to build the adjacency list accordingly.

```cpp
#include <iostream>
#include <vector>
#include <queue>

/**
 * @brief Breadth‑First Search (BFS) traversal of a graph.
 *
 * @param adj   adjacency list of the graph.  adj[u] contains all vertices v such that
 *              there is an edge u → v (for directed graphs) or u – v (for undirected).
 * @param start the vertex from which BFS starts.
 * @return std::vector<int>  the vertices in the order they were visited.
 *
 * Complexity:  O(V + E)  where V = number of vertices, E = number of edges.
 */
std::vector<int> bfs(const std::vector<std::vector<int>>& adj, int start)
{
    int n = static_cast<int>(adj.size());
    std::vector<bool> visited(n, false);
    std::queue<int> q;
    std::vector<int> order;          // result

    visited[start] = true;
    q.push(start);

    while (!q.empty())
    {
        int u = q.front(); q.pop();
        order.push_back(u);

        for (int v : adj[u])
        {
            if (!visited[v])
            {
                visited[v] = true;
                q.push(v);
            }
        }
    }
    return order;
}
```

### How to use it

```cpp
int main()
{
    /* Example: 5‑vertex undirected graph
          0
         / \
        1---2
         \ /
          3
          |
          4
    */
    const int V = 5;
    std::vector<std::vector<int>> adj(V);

    auto addEdge = [&](int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);          // comment out for directed graph
    };

    addEdge(0, 1);
    addEdge(0, 2);
    addEdge(1, 2);
    addEdge(1, 3);
    addEdge(2, 3);
    addEdge(3, 4);

    int startVertex = 0;
    std::vector<int> bfsOrder = bfs(adj, startVertex);

    std::cout << "BFS order starting from vertex " << startVertex << ":\n";
    for (int v : bfsOrder)
        std::cout << v << ' ';
    std::cout << '\n';

    return 0;
}
```

**Output**

```
