#### 2. Return Traversal Order (Vector)
Instead of printing, store in a vector:
```cpp
std::vector<int> bfsOrder(const std::vector<std::vector<int>>& adj, int src) {
    std::vector<bool> visited(adj.size(), false);
    std::queue<int> q;
    std::vector<int> order;

    visited[src] = true;
    q.push(src);

    while (!q.empty()) {
        int u = q.front(); q.pop();
        order.push_back(u); // Store instead of print

        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                q.push(v);
            }
        }
    }
    return order;
}
```

