### C++ Implementation

```cpp
#include <iostream>
#include <algorithm> // For std::min, std::max (optional, just for clarity)

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
public:
    // ---------------------------------------------------------
    // Approach 1: Iterative (Optimal Space Complexity O(1))
    // ---------------------------------------------------------
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        TreeNode* current = root;

        while (current != nullptr) {
            // Both nodes are in the left subtree
            if (p->val < current->val && q->val < current->val) {
                current = current->left;
            }
            // Both nodes are in the right subtree
            else if (p->val > current->val && q->val > current->val) {
                current = current->right;
            }
            // Split happens here (or current matches p/q)
            // This node is the LCA
            else {
                return current;
            }
        }
        return nullptr; // Should not happen if p and q exist in tree
    }

    // ---------------------------------------------------------
    // Approach 2: Recursive (Cleaner code, Space O(H) for stack)
    // ---------------------------------------------------------
    TreeNode* lowestCommonAncestorRecursive(TreeNode* root, TreeNode* p, TreeNode* q) {
        if (!root) return nullptr;

        // If both smaller, go left
        if (p->val < root->val && q->val < root->val) {
            return lowestCommonAncestorRecursive(root->left, p, q);
        }
        // If both larger, go right
        if (p->val > root->val && q->val > root->val) {
            return lowestCommonAncestorRecursive(root->right, p, q);
        }
        // Split or match found
        return root;
    }
};

// ---------------------------------------------------------
// Helper: Build a sample BST for testing
//        6
//       / \
//      2   8
//     / \ / \
//    0  4 7  9
//      / \
//     3   5
// ---------------------------------------------------------
TreeNode* buildSampleBST() {
    TreeNode* root = new TreeNode(6);
    root->left = new TreeNode(2);
    root->right = new TreeNode(8);
    root->left->left = new TreeNode(0);
    root->left->right = new TreeNode(4);
    root->right->left = new TreeNode(7);
    root->right->right = new TreeNode(9);
    root->left->right->left = new TreeNode(3);
    root->left->right->right = new TreeNode(5);
    return root;
}

// Helper to find a node pointer by value (for test setup)
TreeNode* findNode(TreeNode* root, int val) {
    if (!root) return nullptr;
    if (root->val == val) return root;
    if (val < root->val) return findNode(root->left, val);
    return findNode(root->right, val);
}

// Helper to delete tree (prevent memory leaks)
void deleteTree(TreeNode* root) {
    if (!root) return;
    deleteTree(root->left);
    deleteTree(root->right);
    delete root;
}

int main() {
    Solution sol;
    TreeNode* root = buildSampleBST();

    // Test Case 1: LCA of 2 and 8 -> 6 (Root)
    TreeNode* p1 = findNode(root, 2);
    TreeNode* q1 = findNode(root, 8);
    TreeNode* lca1 = sol.lowestCommonAncestor(root, p1, q1);
    std::cout << "LCA(2, 8) = " << lca1->val << " (Expected: 6)\n";

    // Test Case 2: LCA of 2 and 4 -> 2 (One is ancestor of other)
    TreeNode* p2 = findNode(root, 2);
    TreeNode* q2 = findNode(root, 4);
    TreeNode* lca2 = sol.lowestCommonAncestor(root, p2, q2);
    std::cout << "LCA(2, 4) = " << lca2->val << " (Expected: 2)\n";

    // Test Case 3: LCA of 3 and 5 -> 4 (Deep in tree)
    TreeNode* p3 = findNode(root, 3);
    TreeNode* q3 = findNode(root, 5);
    TreeNode* lca3 = sol.lowestCommonAncestor(root, p3, q3);
    std::cout << "LCA(3, 5) = " << lca3->val << " (Expected: 4)\n";

    // Test Case 4: LCA of 0 and 5 -> 2
    TreeNode* p4 = findNode(root, 0);
    TreeNode* q4 = findNode(root, 5);
    TreeNode* lca4 = sol.lowestCommonAncestor(root, p4, q4);
    std::cout << "LCA(0, 5) = " << lca4->val << " (Expected: 2)\n";

    // Cleanup
    deleteTree(root);
    return 0;
}
