{
    std::vector<int> data = { -2, 1, -3, 4, -1, 2, 1, -5, 4 };
    std::cout << "Maximum sub‑array sum = "
              << maxSubArraySum(data) << '\n';   // prints 6
    return 0;
}
```

The maximum sub‑array in the example is `[4, -1, 2, 1]`, whose sum is `6`.

